func:
// Gateway (edge node) heartbeat.
//
// WHAT MAKES THE GATEWAY SHOW 'ONLINE'. The ingestion daemon stamps gateways.last_heartbeat on
// every node-level message -- NBIRTH, NDATA or NDEATH -- and the dashboard derives staleness from
// it at read time with a 90s threshold. Beating every 30s allows three missed beats before this
// appliance is reported STALE.
//
// PAYLOAD IS JSON, NOT PROTOBUF, and that is a supported encoding rather than a shortcut: the
// ingestion daemon's parse_sparkplug_payload() tries protobuf first and falls back to this shape.
// It is what the platform's own simulator publishes. If you later add a protobuf encoder, nothing
// else in this flow has to change -- the topic is what identifies the asset.

const GROUP = '__SPARKPLUG_GROUP__';
const NODE  = '__SPARKPLUG_ID__';
const type  = msg.payload;   // 'NBIRTH' or 'NDATA'

// UPTIME FROM FLOW CONTEXT, NOT process.uptime().
//
// A Node-RED function node runs in a SANDBOX with no `process` global. `process.uptime()` is not a
// syntax error and is not caught at deploy time -- it throws at the first tick:
//
//     ReferenceError: process is not defined
//
// and because the throw happens BEFORE msg is returned, nothing is ever published. The broker node
// connects, the editor looks healthy, and the gateway sits in AWAITING_BIRTH forever with the only
// evidence in the appliance's own logs. Verified against Node-RED 5.0.2.
//
// The first tick records its own start instead, which is the process start for every practical
// purpose here -- this node runs on the same 'on start' inject that produces the NBIRTH.
let startedAt = context.get('startedAt');
if (!startedAt) {
    startedAt = Date.now();
    context.set('startedAt', startedAt);
}

let seq = context.get('seq') || 0;
// Sparkplug sequence numbers wrap at 256. A birth resets it to 0 by specification.
seq = (type === 'NBIRTH') ? 0 : (seq + 1) % 256;
context.set('seq', seq);

msg.topic = `spBv1.0/${GROUP}/${type}/${NODE}`;
msg.payload = {
    timestamp: Date.now(),
    seq,
    metrics: [
        // Read by ingestion's process_node_message(): a Gateway_Status string metric OVERRIDES the
        // status implied by the message type. Sending it explicitly means this appliance says what
        // it thinks its own state is rather than having it inferred.
        { name: 'Gateway_Status', type: 'String', value: 'ONLINE' },
        { name: 'bdSeq', type: 'Int64', value: seq },
        { name: 'Uptime_s', type: 'Int64', value: Math.floor((Date.now() - startedAt) / 1000) }
    ]
};
return msg;

// ZERO-TOUCH ONBOARDING, demonstrated.
//
// This publishes a birth certificate for a device the platform has NEVER HEARD OF. That is not a
// mistake and it is not an error path -- it is how devices are meant to arrive:
//
//   1. an unregistered device announces itself with a DBIRTH
//   2. the ingestion daemon writes it into the QUARANTINE QUEUE and drops its data
//   3. an operator approves it in the dashboard, choosing its name and cell
//   4. from then on its DDATA is accepted and stored
//
// Nothing has to be pre-registered, and this flow deliberately does NOT call the platform's REST
// API to create the device. Announcing yourself over Sparkplug is the whole interface.
//
// CHANGE THIS to whatever your machine should be called, then click the inject node again.
const DEVICE_ID = 'press-01';

const GROUP = '__SPARKPLUG_GROUP__';
const NODE  = '__SPARKPLUG_ID__';

msg.topic = `spBv1.0/${GROUP}/DBIRTH/${NODE}/${DEVICE_ID}`;
msg.payload = {
    timestamp: Date.now(),
    seq: 0,
    metrics: [
        // Every metric this device will ever publish must be DECLARED in its birth certificate.
        // Sparkplug binds names to aliases here; a DDATA metric whose alias was never declared
        // cannot be resolved and is dropped (the daemon then asks this node to rebirth).
        { name: 'Device Control/Rebirth', type: 'Boolean', value: false },
        { name: 'Properties/Manufacturer', type: 'String', value: 'Example Machine Co' },
        { name: 'Temperature', type: 'Float', value: 20.0 },
        { name: 'CycleCount', type: 'Int64', value: 0 }
    ]
};

node.warn(`Published DBIRTH for '${DEVICE_ID}'. It will appear in the dashboard's quarantine queue — approve it there, then publish DDATA on spBv1.0/${GROUP}/DDATA/${NODE}/${DEVICE_ID}.`);
return msg;
